-- Apply with Alembic or Supabase SQL editor. The application also creates these tables for local development.
CREATE TABLE IF NOT EXISTS profiles (id VARCHAR(128) PRIMARY KEY, full_name VARCHAR(200), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(128) NOT NULL, title VARCHAR(200) NOT NULL, summary TEXT, active_room_id VARCHAR(80), active_intent VARCHAR(80), context_json JSONB, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), last_message_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id VARCHAR(36) PRIMARY KEY, conversation_id VARCHAR(36) REFERENCES conversations(id) ON DELETE CASCADE, user_id VARCHAR(128) NOT NULL, role VARCHAR(20) NOT NULL, content TEXT NOT NULL, metadata_json JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS memories (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(128) NOT NULL, memory_type VARCHAR(80) NOT NULL, key VARCHAR(120) NOT NULL, value_json JSONB NOT NULL, source_conversation_id VARCHAR(36), confidence DOUBLE PRECISION, last_referenced_at TIMESTAMPTZ DEFAULT now(), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), is_active BOOLEAN DEFAULT true);
CREATE INDEX IF NOT EXISTS ix_memories_user_active ON memories(user_id, is_active);
